"""Library of Congress Subject Headings (LCSH) Standard Authority File.

Authoritative controlled vocabulary and thesaurus for cataloging and search expansion.
"""

from typing import Dict, List, Optional
from dataclasses import dataclass, field


@dataclass
class SubjectHeadingRecord:
    heading_id: str
    term: str
    marc_tag: str
    lcc_class: str
    ddc_number: str
    broader_terms: List[str] = field(default_factory=list)
    narrower_terms: List[str] = field(default_factory=list)
    related_terms: List[str] = field(default_factory=list)
    scope_note: str = ""


LCSH_RECORDS: Dict[str, SubjectHeadingRecord] = {}

def _rec(hid: str, term: str, tag: str, lcc: str, ddc: str, bt: List[str], nt: List[str], rt: List[str], note: str):
    LCSH_RECORDS[hid] = SubjectHeadingRecord(hid, term, tag, lcc, ddc, bt, nt, rt, note)

