def lookup_subject(term: str) -> Optional[SubjectHeadingRecord]:
    """Look up subject heading by exact term or ID."""
    clean = term.strip().lower()
    for rec in LCSH_RECORDS.values():
        if rec.heading_id.lower() == clean or rec.term.lower() == clean:
            return rec
    return None

def search_subjects(query: str, limit: int = 25) -> List[SubjectHeadingRecord]:
    """Search subject headings by keyword substring."""
    q = query.strip().lower()
    matches = []
    for rec in LCSH_RECORDS.values():
        if q in rec.term.lower():
            matches.append(rec)
            if len(matches) >= limit:
                break
    return matches
